from math import inf

def solve():
    n = int(input())
    a = list(map(int, input().split()))
    min_ops = inf
    for ops in range(n - 1):
        for comb in combinations(range(1, n), ops):
            new_a = a.copy()
            for i in comb:
                new_a[i] += 1
                if i + 1  n:
