                for i in range(n):
                    for j in range(m):
                        if a[i] - b[j] > 0:
                            pa[i] = a[i] - b[j]
                            pb[j] = b[j] - a[i]
                            a[i] = pa[i]
                            b[j] = pb[j]

                            if pa[i] <= 0:
                                pa[i] = float("-inf")

                            if pb[j] <= 0:
                                pb[j] = float("-inf")

                            turn = 1
                            break
                else:
