@lru_cache(None)
def solve(s):
    n = len(s)
    dp = [[0] * (n + 1) for _ in range(2)]
    dp[0][0] = 1

    for i in range(1, n + 1):
        for j in range(2):
            if s[i - 1] == '?':
                dp[i][j] += dp[i - 1][0] + dp[i -\1][1]
            elif s[i - 1]!= '0' or j == 1:
                dp[i][j] += dp[i -\1][j]

    return dp[n][1]

