def sequence_of_spells(n):
    if n % 2 == 0:
        m = n//2
        ans = [1] * (m-1) + [2]
        return '{}\n{}'.format(len(ans), '\n' +''.join(map(str, ans))
    elif n == 2:
        return -1
    elif n == 3:
        return '1'
    else:
        seq = []
        i = n
        while i > 3:
            if i % 4 == 3:
                seq += [2, 2]
                i = (i+1) // 2
            else:
                seq += [1]
                i = (i-1) // 2
        if i ==\= 3:
            seq += [2]
        return '{}\n{}'.format(len(seq), '\n' +''.join(map(str, seq))

