        return 0 <= x[0] < n and 0 <= x[1] < m

    def get_dist(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def min_obstacle(n, m, a, b):
        q = [(0, a)]
        vis = {(a[0], a[1]): 0}
        while q:
            d, x = heapq.heappop(q)
            for i in range(4):
                y = [x[1][0] + dx[i], x[1][1] + dy[i]]
                if in_range(y) and y not in vis:
                    heapq.heappush(q, (d + 1, y))
                    vis[y] = d + 1
        if b in vis:
            return vis[b]
        else:
            return sys.maxsize

