def can_merge(t1, t2):
    while t1 and t2 and t1[-1] == t2[-1]:
        if t1[-1] == t2[-1] == 'B':
            t1.pop()
            t2.pop()
        elif t1[-1] == t2[-1] == 'R':
            t1.pop()
            t2.pop()
        else:
            break
    return not (t1 and t2)

