        t = ''.join(ns)
        for i in range(1, n + 1):
            if t[i - 1] == 'L':
                if not all(t[j] == 'L' for j in range(i - 1)):
                    pos = p[i -\ 1]
                    break
            elif t[i -\ 1] == 'R':
                if not all(t[j] == 'R' for j in range(i, n)):
                    pos = p[i -\ 1]
                    break
        if pos!= -1:
            break
    if pos!= -1:
        return pos +\ 1
    return -1
