                return a[1:] == b[:]
            else:
                return False
        a[1] = min(a[0], a[1])
        a.pop(0)
        if a[1:] == b: return True

        a[1] = max(a[0], a[1])
        a.pop(0)
        if a[1:] == b: return True
    return a == b

